-- challenge chal_quiz_qpr_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_211', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-2-1' AND is_deleted = false LIMIT 1), 'load-profiles-evidence', 'Load profiles: what did this run actually test?', 'Two load profiles for POST /api/submissions, the endpoint that must accept 340 submissions per second on exam day within 2 s at p95. Decide what each run tested and which numbers you can compare with the target.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_211'), 'k6 script for the exam-day test of POST /api/submissions (k6 option names as in current releases; check current docs):
export const options = {
  scenarios: {
    exam_day: {
      executor: ''ramping-vus'',
      startVUs: 0,
      stages: [
        { duration: ''2m'', target: 340 },
        { duration: ''10m'', target: 340 },
        { duration: ''1m'', target: 0 },
      ],
    },
  },
};
export default function () {
  http.post(''https://api.codedev.test/api/submissions'', payload, params);
  sleep(1);
}

k6 output, filtered to the 10-minute hold:
http_req_duration..........: avg=571ms p(95)=1.21s
http_reqs..................: 129840  216.4/s
vus........................: 340

Statement: "This run tested the exam-day peak: during the 10-minute hold it kept 340 submissions per second arriving at the API."', 'single_choice'::question_type, 'False. ramping-vus ramps virtual users, not requests per second: target 340 means 340 concurrent loops, and each loop sends one request, waits for the response, then sleeps 1 s. One iteration takes about 0.571 + 1 = 1.571 s, so 340 VUs produce about 340 / 1.571 = 216 requests per second, which is what http_reqs shows. This is a closed model: when the API slows down, the VUs wait longer and send less, so the load drops exactly when the system struggles. To hold 340 arrivals per second whatever the latency, use an arrival-rate executor (constant-arrival-rate or ramping-arrival-rate in k6) with enough VUs allocated. The misconception is reading a VU target as a request rate.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_211') AND order_index = 1)
    RETURNING id
)
