-- challenge chal_coding_qpr_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qpr_212', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-2-1' AND is_deleted = false LIMIT 1), 'load-profile-schedule', 'Turn a load profile into a per-second schedule', 'Exam day on CodeDev peaks at 340 submissions per second. Before the next load test of POST /api/submissions, the team writes the load profile as stages, like a k6 ramping-arrival-rate scenario: the arrival rate starts at start_rate and every stage moves it in a straight line to the stage''s target over duration_s seconds (a ramp when the target differs, a hold when it is the same). Write build_schedule(profile): the per-second schedule the generator will follow, its totals and its steady-state window, or an error for a profile that cannot be run.

Input (stdin, JSON): {"start_rate": 0, "stages": [{"duration_s": 60, "target": 340}, ...]}. start_rate is optional (default 0).

Validation, in this order; the first problem found is the answer:
- stages missing, not a list or empty -> {"error": "no stages"}
- start_rate not an integer >= 0 -> {"error": "bad start_rate"}
- then for each stage n = 1, 2, ... in order: duration_s not an integer >= 1 -> {"error": "stage n: bad duration_s"}; target not an integer >= 0 -> {"error": "stage n: bad target"}
- total duration over 3600 s -> {"error": "longer than 3600 s"}
(30.0, "30", true and false are not integers.)

Schedule: one entry per second of the test. In a stage that moves the rate from a (the rate before the stage: start_rate, or the previous stage''s target) to b over d seconds, second k of the stage (k = 1 .. d) has the target rate floor(a + (b - a) * k / d): the rate reached at the end of that second, rounded down, also when the rate goes down. total_requests is the sum of the schedule, peak_rate its maximum, duration_s its length.

steady is the longest stage that holds a non-zero rate (b == a and b > 0), as {"start_s": second the stage starts (the test starts at 0), "end_s": start_s + d, "rate": b}; the earliest such stage on a tie; null when no stage holds a non-zero rate.

Output (stdout, JSON), for stages 0 -> 10 over 5 s, hold 10 s, 10 -> 0 over 5 s:
{"duration_s": 20, "total_requests": 150, "peak_rate": 10, "steady": {"start_s": 5, "end_s": 15, "rate": 10}, "schedule": [2, 4, 6, 8, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 10, 8, 6, 4, 2, 0]}', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212'), 1, 'At the end of second k of a stage that goes from a to b in d seconds, which fraction of the straight line have you covered, and which way does "rounded down" go when b is smaller than a?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212'), 2, 'Look at three places: where each stage gets its starting rate (the previous target, or start_rate for the first stage), whether you validate every stage before you build anything and in the listed order, and the condition for steady: a hold keeps the rate the same, and a hold at 0/s is a pause, not a steady state.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212'), 3, 'A similar stage on other numbers: from 90 down to 20 over 4 seconds the line reaches 72.5, 55, 37.5 and 20 at the end of seconds 1 to 4, so the targets are 72, 55, 37, 20. From 20 up to 90 over 4 seconds they are 37, 55, 72, 90. In Python, -17.5 rounded down is -18, while int(-17.5) is -17.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
