       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_212'), 'Fractional duration and negative target: first problem wins', '{"start_rate":10,"stages":[{"duration_s":10,"target":20},{"duration_s":20,"target":-5},{"duration_s":1.5,"target":0}]}', '{"error":"stage 2: bad target"}', 2, false, true, 5),
