-- challenge chal_quiz_qpr_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_221', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-2-2' AND is_deleted = false LIMIT 1), 'throughput-errors-evidence', 'Throughput & error rate: read the status counts', 'One steady-state window of the exam-day load test of POST /api/submissions, as counts by status and as the k6 summary line. Decide what the endpoint served and what the error rate really is.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_221'), 'Exam-day load test, constant arrival rate, steady-state window 10:05:00-10:10:00 (300 s). POST /api/submissions, requests sent inside the window, by status:
 status            | requests
 201 Created       |  97,760
 429 Too Many Req. |   5,400
 401 Unauthorized  |     340
 503 Unavailable   |     300
 0 (timeout, 10 s) |     200
 total             | 104,000

Statement: "104,000 requests in 300 s is 346.7 per second, so in this window the submit endpoint handled the exam-day peak of 340 submissions per second."', 'single_choice'::question_type, 'False. 346.7/s is the offered throughput: what the generator sent. Handled means accepted, and only the 97,760 responses with 201 created a submission: 97,760 / 300 = 325.9 per second, below 340. The 5,400 responses with 429 were turned away by the rate limiter, the 503s and timeouts failed, and the 401s never reached the submit logic. The misconception is to report requests per second as capacity; report offered throughput and served throughput (goodput) side by side.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_221'), 'Same window, same counts by status:
 201: 97,760   429: 5,400   401: 340   503: 300   0 (timeout): 200   total: 104,000

k6 end-of-test summary, filtered to the window (default response callback; the summary format differs between k6 versions, check current docs):
http_req_failed................: 6.00%  6240 out of 104000

Statement: "The 6.00% includes the 5,400 throttled responses and the 340 responses with 401; server errors and timeouts together are 500 of the 104,000 requests, about 0.48%."', 'single_choice'::question_type, 'True. By default k6 counts a request as failed when no response arrived or its status is outside 200-399, so 5,400 + 340 + 300 + 200 = 6,240 failed, 6.00%. That one number mixes three different signals: the rate limiter working (429), a broken test script (401 from expired tokens in the test data) and the server failing (503 and timeouts: 500 requests, 0.48%). Each needs a different action, so count them separately; in k6 you can also change what counts as failed with setResponseCallback. The misconception is to read http_req_failed as the server error rate.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_qpr_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qpr_222', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-2-2' AND is_deleted = false LIMIT 1), 'throughput-error-rate-from-log', 'Throughput & error rate from a load test log', 'The exam-day load test of the CodeDev API recorded one row per request. The ramps at the start and the end ran at lower rates, so the report uses the steady-state window only. Write summarize(run): offered and served throughput and the error rate, per endpoint and in total, for the requests the generator sent inside the window.

Input (stdin, JSON): {"window": {"start_ms": 300000, "end_ms": 1200000}, "requests": [[sent_ms, "POST /api/submissions", status, duration_ms], ...]}. sent_ms is when the request was sent (ms since the test started), duration_ms how long the client waited for it; rows can be in any order (the tool logs them when they complete). status 0 means no response: the client timed out or the connection failed.

Rules:
- The window is [start_ms, end_ms): a request belongs to it when start_ms <= sent_ms < end_ms, wherever its response arrived. end_ms - start_ms must be a whole number of seconds and at least 1000 ms, otherwise the output is {"error": "window must be a whole number of seconds"}.
- Every request in the window counts in requests and in exactly one class: 200-399 ok; 429 throttled (turned away by the rate limiter: not served, but not a server failure); any other 400-499 client_errors (usually a broken test script, e.g. 401 from an expired token); 500-599 errors; 0 errors, and also counted in timeouts.
- For each endpoint with requests in the window, and for "total" (all endpoints): the counts requests, ok, errors, timeouts, throttled, client_errors, and rps = round(requests / window seconds, 2) (offered throughput), ok_rps = round(ok / window seconds, 2) (served throughput), error_rate = round(errors / requests, 4), null when requests is 0. Endpoints without requests in the window are left out; total is always present.

Output (stdout, JSON): {"window_s": 900, "endpoints": {"GET /api/leaderboard": {"requests": ..., "ok": ..., "errors": ..., "timeouts": ..., "throttled": ..., "client_errors": ..., "rps": ..., "ok_rps": ..., "error_rate": ...}, ...}, "total": {...}}', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_222'), 1, 'A request sent at 299.9 s is answered at 300.4 s. Which second of the profile offered it, and what happens to a window''s numbers if slow requests are counted when they finish instead of when they were sent?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_222'), 2, 'Check three things: the window test uses sent_ms only (start inclusive, end exclusive); the status checks run in the right order (429 before the other 4xx); and a row with status 0 is a request that failed, counted both in errors and in timeouts, not a row without data.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_222'), 3, 'A small example on other data: window [0, 2000) and rows [500, "GET /x", 200, 20], [1200, "GET /x", 429, 3], [1900, "GET /x", 0, 1000], [2000, "GET /x", 500, 9]. Three requests are in the window (the 500 sent at 2000 belongs to the next one): ok 1, throttled 1, errors 1 of which timeouts 1, rps 1.5, ok_rps 0.5, error_rate 0.3333.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
