-- challenge chal_quiz_qpr_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_231', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-2-3' AND is_deleted = false LIMIT 1), 'coordinated-omission-evidence', 'Coordinated omission: what the generator did not send', 'Two pieces of evidence from load tests that ran while the CodeDev API paused behind a lock. Decide what the reported latencies say about the learners'' waits, and which latency a request really had.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_231'), 'wrk (closed loop: each of the 4 connections sends its next request only after the previous response) against the leaderboard, output trimmed (format varies by version; check current docs):
$ wrk -t2 -c4 -d60s --latency https://api.codedev.test/api/leaderboard
  Latency   21.30ms avg   40.12ms stdev   1.52s max
  Latency Distribution
     50%   18.10ms
     99%   48.70ms
  11262 requests in 60.00s
Requests/sec: 187.70

API log in the same minute: 12:00:31.0 - 12:00:32.5 every leaderboard query waited for one lock (a 1.5 s pause). Learners open the leaderboard at about 190 requests per second, whatever the API does.

Statement: "Only 4 of the 11,262 recorded requests were slower than 48.7 ms, so the 1.5 s pause delayed less than 1% of the learners'' leaderboard requests in this minute."', 'single_choice'::question_type, 'False. During the pause all 4 connections were stuck, each with one request in flight, so the generator sent nothing for 1.5 s: those 4 slow samples are all it recorded. Learners do not wait for each other. At 190 per second about 285 of them opened the leaderboard during the pause and waited between a few ms and 1.5 s, about 0.75 s on average. That is about 2.5% of the minute''s 11,400 requests, and a p99 near 0.9 s instead of 48.7 ms. This is coordinated omission: the generator slowed down together with the system and omitted exactly the samples that would have shown the problem. The misconception is to treat a closed-loop tool''s percentiles as the users'' percentiles.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_231'), 'Fixed-rate test of POST /api/submissions: request seq is due at intended_ms = seq * 10 (100 requests per second); the generator has one connection and, after a stall, sends the overdue requests back to back. Excerpt of its log (ms since the start):
 seq | intended_ms | sent_ms | done_ms | done - sent
  40 |       400   |   400.0 |   418.2 |    18.2
  41 |       410   |   410.0 |  1630.5 |  1220.5
  42 |       420   |  1630.5 |  1651.0 |    20.5
  43 |       430   |  1651.0 |  1670.4 |    19.4

Statement: "Measured from its intended send time, request 43 took 1,240.4 ms, although the done - sent column reports 19.4 ms for it."', 'single_choice'::question_type, 'True. 1670.4 - 430 = 1240.4 ms. In an open model the request exists from its scheduled time on, like a learner who clicks Submit at 430 ms: the response arrived at 1670.4 ms, so that learner waited 1,240.4 ms. done - sent measures only the service time after the generator managed to send it; the 1,220 ms it spent waiting for the connection is queueing delay that a real user would have felt. Measuring from the intended time is what wrk2 does (check current docs). The misconception is that the request was only slow once it was sent.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_qpr_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qpr_232', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-2-3' AND is_deleted = false LIMIT 1), 'spot-ai-coordinated-omission', 'Spot the AI Mistake: a load test report that hides the generator''s stalls', 'The team load-tests POST /api/submissions at a fixed rate (an open model): the generator has a schedule with one request every interval_ms, whatever the server does. A developer sent this request to an AI assistant:

"Write analyze(run) in Python for the log of our fixed-rate load test. The generator sends request seq (0, 1, 2, ...) at start_ms + seq * interval_ms and logs [seq, sent_ms, done_ms] for each request when its response arrives. Report the number of requests, p50, p95, p99 and max latency in ms (nearest-rank percentiles, rounded to 1 decimal), and how many requests took longer than target_ms. Reject an interval_ms or target_ms that is not > 0."

The assistant''s code is the starter. On the two recorded runs used in review its numbers were plausible, so it became the team''s report script. Then a run in which the server paused for 1.2 s (every in-flight submission stuck behind one lock) came back with p99 under 30 ms and no request over target, while learners in the same exam rehearsal waited seconds. Find the mistake and fix analyze(run).

Input (stdin, JSON): {"start_ms": 0, "interval_ms": 5, "target_ms": 2000, "requests": [[seq, sent_ms, done_ms], ...]}, times in ms since the test started. Rows can be in any order (they are logged on completion). When its connections are busy, the generator sends a request late, as soon as one is free.

Percentiles: nearest-rank on the sorted latencies, rank = ceil(p / 100 * n), value = sorted[rank - 1]; null when there are no requests. A request is over target when its latency is greater than target_ms.

Output (stdout, JSON): {"requests": 400, "p50": 18.7, "p95": 28.6, "p99": 29.6, "max": 29.9, "over_target": 0}, or {"error": "interval_ms and target_ms must be > 0"}.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
