INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_311', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-3-1' AND is_deleted = false LIMIT 1), 'warm-up-evidence', 'Warm-up: read the windows before you compare', 'Two statements on the per-window p95 of a load test that started on freshly deployed pods, and on a comparison with a second run started on the same pods after it.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_311'), 'Run A: k6, constant arrival rate of 200 req/s on GET /api/leaderboard, started 40 s after a deploy replaced every API pod. The p95 of each 30 s window (computed from the raw samples, nearest-rank):

window     0-30s  30-60s  60-90s  90-120s  120-150s  150-180s  180-210s  210-240s
p95 (ms)     912     388     204      131       126       129       124       127
requests   5,980   6,010   6,002    5,995     6,004     5,998     6,001     6,003

k6 summary for the whole run: http_req_duration p(95)=371ms

Statement: "Reported as the p95 of the leaderboard, the 371 ms of the summary would mostly describe the first two windows: from 90 s on, every window''s p95 is between 124 and 131 ms."', 'single_choice'::question_type, 'True. The windows hold about the same number of requests, so the whole-run p95 is the value with 5% of all 48,000 samples above it, about 2,400 samples. The first two windows alone have enough slow requests (cold caches, empty connection pools, unoptimised code paths after a restart) to fill most of that top 5%, which drags the whole-run p95 up to 371 ms although six of eight windows sit between 124 and 131 ms. The misconception is that a whole-run percentile is a stable property of the service: it depends on how much warm-up the run happened to contain. Report the warm-up and the steady state separately.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_311'), 'Same pods as run A above. Right after run A finished, a developer deployed nothing, enabled a new cache flag for the leaderboard query through the admin API, and started run B with the same k6 script and rate.

run      whole-run p95   p95 of windows from 90 s on
A        371 ms          124-131 ms
B        129 ms          125-132 ms

PR description: "Leaderboard cache: p95 371 ms -> 129 ms (-65%), see k6 runs A and B."

Statement: "Runs A and B show that the cache flag cut the p95 of the leaderboard by about 65%."', 'single_choice'::question_type, 'False. Run A started on cold pods and run B started on pods that run A had just warmed up, so the two whole-run numbers differ mostly by warm-up, not by the flag. Compared on their steady parts, both runs sit at about 125-131 ms: the evidence shows no measurable effect of the flag at all. The misconception is that the same script and rate make two runs comparable; they also need the same starting state, or the warm-up excluded from both, before any difference is attributed to the change.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_311') AND order_index = 2)
    RETURNING id
)
