-- challenge chal_coding_qpr_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qpr_312', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-3-1' AND is_deleted = false LIMIT 1), 'exclude-the-warm-up', 'Exclude the warm-up, then compare two runs', 'A pull request on CodeDev claims that a change made POST /api/submissions 40% faster at p95. The evidence is two recorded load test runs: the baseline ran right after a deploy on cold pods, the candidate on pods that were already warm. Write compare_runs(case) so that the comparison uses only the steady part of each run, with a warm-up rule that anyone can re-run and get the same answer.

Input (stdin, JSON): {"window_ms": W, "band": b, "baseline": samples, "candidate": samples}. Each sample is [t_ms, latency_ms]: t_ms is the time since the start of that run, latency_ms the response time. Samples can arrive in any order. W is a positive integer, 0 < b < 1.

Rule, applied to each run on its own:
1. A sample is valid when it is a list of exactly two numbers (int or float, not bool) with t_ms >= 0 and latency_ms > 0. Drop every other sample and count it in "dropped".
2. Put each valid sample in window floor(t_ms / W). Windows without samples are ignored. Compute the p95 of every non-empty window and list them in time order: V[0], ..., V[n-1].
3. Reference R = statistics.median(V[n // 2:]) (the median of the second half of the windows; the mean of the two middle values when that half has an even length).
4. The warm-up ends at the smallest index i such that every window from i to the end is inside the band: abs(V[j] - R) <= b * R for all j >= i. warmup_end_ms = (window number of V[i]) * W.
5. The steady state needs at least 3 windows (n - i >= 3). If there is no such i, or no valid sample at all, the run has no steady state: warmup_end_ms and p95 are null and every valid sample counts as excluded.
6. The steady samples are the valid samples with t_ms >= warmup_end_ms.

Percentiles (everywhere): nearest-rank on sorted samples, rank = ceil(p/100 * n), value = sorted[rank - 1]; an empty list has no percentile (null). The starter already has this percentile function.

Output (one JSON line): {"baseline": run, "candidate": run, "p95_change_pct": x, "naive_p95_change_pct": y}, where run = {"warmup_end_ms": int or null, "excluded": valid samples before warmup_end_ms, "steady_samples": count, "p95": p95 of the steady samples rounded with round(v, 1), or null, "dropped": count}.
- p95_change_pct = round((candidate p95 - baseline p95) / baseline p95 * 100, 1), using the unrounded p95 values; null when either run has no steady state.
- naive_p95_change_pct is the same formula on the p95 of all valid samples of each run (warm-up included), null when either run has no valid sample. It is the number the pull request reported.

Example: {"window_ms": 10000, "band": 0.2, "baseline": [...], "candidate": [...]} -> {"baseline": {"warmup_end_ms": 30000, "excluded": 60, "steady_samples": 100, "p95": 95.1, "dropped": 0}, "candidate": {...}, "p95_change_pct": -3.2, "naive_p95_change_pct": -68.5}.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_312');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_312'), 1, 'Take a run whose window p95 values are 410, 180, 240, 112, 108, 105, 110, 104. The second window is already close to the end value - so why can it not be the end of the warm-up?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_312'), 2, 'Look at the order of the work: drop invalid samples first, then build the windows from valid samples only and skip empty windows, then take the reference from the second half of the window list, and only then search for the first window after which nothing leaves the band. Searching from the last window backwards is the easiest way to get "every later window" right. Check the 3-window minimum before you report a steady state.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_312'), 3, 'A worked example with other numbers: window p95 values [600, 200, 130, 100, 104, 96, 101], band 0.1, W = 10000, no empty windows. n = 7, the second half is V[3:] = [100, 104, 96, 101], so R = 100.5 and the band is 90.45 to 110.55. From the end: 101, 96, 104, 100 are inside, 130 is not, so the steady state starts at index 3 with 4 windows (at least 3) and warmup_end_ms = 30000.');
