-- challenge chal_quiz_qpr_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_321', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-3-2' AND is_deleted = false LIMIT 1), 'find-the-first-bottleneck-evidence', 'Find the First Bottleneck: read the evidence', 'The weekly report said POST /api/submissions averages 120 ms; learners in the exam rehearsal waited up to 6 seconds at the deadline while API CPU sat at 40%. Six statements on one evidence pack - the k6 summary (A), the traces (B) and the metrics (C) - take you from reading the evidence to a hypothesis, past a wrong explanation, to the mechanism, the fix and its verification.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
