WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_331'), 'Step load test of POST /api/submissions on ONE API instance (pool of 6 DB connections), 2 minutes per step, warm-up excluded:

offered/s  achieved/s  p95       errors
   100       100.0      66 ms    0.00%
   110       110.0      70 ms    0.00%
   120       119.9      79 ms    0.00%
   130       129.9     104 ms    0.00%
   140       139.8     205 ms    0.00%
   150       149.1     820 ms    0.00%
   160       157.2     3.9 s     0.00%
   170       157.9     8.4 s     0.20%
   180       158.1    12.1 s     2.60%

Statement: "From 160/s on, the extra offered load is not served at all: achieved throughput stays at about 158/s, so every additional request per second only adds to a waiting line, and p95 grows with it."', 'single_choice'::question_type, 'True. The instance''s ceiling is about 158 requests per second (6 connections / 38 ms hold time). Above it, achieved throughput stops following offered load, and the difference - about 3 requests per second at 160, 12 at 170, 22 at 180 - joins a queue that grows for the whole step, which is why p95 climbs from seconds to more than 12 s and why timeouts appear at the end. The misconception is that higher load gives proportionally more throughput with somewhat slower responses; past the ceiling it gives no more throughput and much slower responses.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_331') AND order_index = 1)
    RETURNING id
)
