        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_331'), 'Step load test of POST /api/submissions on ONE API instance (pool of 6 DB connections), 2 minutes per step, warm-up excluded:

offered/s  achieved/s  p95       errors
   100       100.0      66 ms    0.00%
   110       110.0      70 ms    0.00%
   120       119.9      79 ms    0.00%
   130       129.9     104 ms    0.00%
   140       139.8     205 ms    0.00%
   150       149.1     820 ms    0.00%
   160       157.2     3.9 s     0.00%
   170       157.9     8.4 s     0.20%
   180       158.1    12.1 s     2.60%

Statement: "The knee of this instance is at 170/s, because 170/s is the first step where achieved throughput falls below 95% of the offered rate."', 'single_choice'::question_type, 'False. Throughput is the last signal to move: it only drops below the offered rate once the queue grows without limit. Latency moves first. The p95 more than doubles from the low-load 66 ms by 140/s (205 ms) and reaches 820 ms at 150/s, while throughput still keeps up. With the course''s rule (the last step before the first step that breaks any of throughput, latency or errors), the knee is 130/s. Planning capacity at 170/s would put learners in front of a multi-second queue. The misconception is to read the knee from the throughput curve alone.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_331') AND order_index = 2)
    RETURNING id
)
