-- challenge chal_quiz_qpr_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_411', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-4-1' AND is_deleted = false LIMIT 1), 'is-it-really-faster', 'Is it really faster? Read the runs', 'The perf bot said PR #1042 made GET /api/leaderboard 11% faster, from one run of each build. Two statements on that comment and on an A/A check of the unchanged code: what one run per side can and cannot tell you.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_411');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_411');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_411'), 'PR #1042 "leaderboard: cache rank lookups" - comment from the perf bot
(k6, GET /api/leaderboard on staging, 150 req/s for 60 s, one run per build):
  main     http_req_duration p(95)=212ms
  branch   http_req_duration p(95)=188ms   -11.3%  FASTER

A/A check the next morning: the same commit of main (8c41d2e), five runs back to back,
same k6 script, same staging host, nothing changed between runs:
  run 1  p(95)=196ms
  run 2  p(95)=231ms
  run 3  p(95)=188ms
  run 4  p(95)=214ms
  run 5  p(95)=205ms

Statement: "The 24 ms gap reported on PR #1042 is smaller than the spread between runs of unchanged code, so these two runs alone cannot tell whether the change made the endpoint faster."', 'single_choice'::question_type, 'True. With no code change at all, the p95 of main moved between 188 and 231 ms, a 43 ms spread; run 3 of main even matched the branch''s 188 ms exactly. A 24 ms gap between one run of each build fits inside that noise, so it could come from the run, not from the change. This does not prove the cache is useless: it means one run per side cannot separate the change from the noise. You need several runs per build, interleaved, and an interval for the difference. The misconception is to read a percentage with a FASTER label as a measured effect.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_411'), 'k6 end-of-test summaries of the two runs behind PR #1042 (trimmed):
  main    http_reqs: 9000   http_req_duration: avg=97.4ms med=81ms p(95)=212ms
  branch  http_reqs: 9000   http_req_duration: avg=94.1ms med=80ms p(95)=188ms

Five A/A runs of main on the same host, 9,000 requests each, gave p(95) values from 188 ms to 231 ms.

Statement: "Each p95 is computed from 9,000 requests, so it is precise to a few milliseconds; with that many samples per run, the 24 ms gap between the two runs is a real improvement."', 'single_choice'::question_type, 'False. 9,000 samples describe that one run precisely, but every request in a run shares the run''s conditions: what else ran on the staging host, the cache and buffer state, a vacuum or garbage collection that happened to start, the hardware the VM landed on. Those conditions change from run to run, and the A/A check measures their effect directly: a 43 ms spread with 9,000 requests in every run. More requests per run do not shrink run-to-run variation; more runs do. Treat the run as the unit of comparison. The misconception is that a large sample count inside one run gives confidence about the difference between builds.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_qpr_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qpr_412', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-4-1' AND is_deleted = false LIMIT 1), 'decide-if-b-is-faster', 'Decide whether build B is really faster', 'After PR #1042 was merged on the strength of one run per build, the CodeDev team changed the perf bot: every pull request now gets at least 3 interleaved runs of main (A) and of the branch (B) against GET /api/leaderboard, and the bot posts a verdict only when the difference between the builds is larger than the run-to-run noise. Write compare_runs(case) for the bot. The runner has no load generator: the input is the recorded latencies of each run.

Input (stdin, one test case): {"a": [[latency_ms, ...], ...], "b": [[latency_ms, ...], ...], "resamples": R, "seed": S}. a and b hold one list of samples (ms) per run. R >= 1, 0 <= S < 2**31.

1. p95 of each run, nearest rank (the definition used in the whole course): sort the run''s samples, rank = ceil(95/100 x n), p95 = sorted[rank - 1]. Compute the rank with integers to stay exact: (95 * n + 99) // 100.
2. diff = mean(p95s of A) - mean(p95s of B). Positive means B is faster.
3. Bootstrap over runs: the run is the unit, never a single sample. PRNG: state starts at S; next() sets state = (1103515245 * state + 12345) % 2**31 and returns the new state; drawing from a list of k values picks the value at index next() % k. For each of the R resamples, in this order: draw len(a) values from A''s p95 list (with replacement), then len(b) values from B''s p95 list; the resample''s difference is mean(drawn A) - mean(drawn B). The state carries over from one resample to the next.
4. Sort the R differences. The 95% interval is [low, high] = their nearest-rank 2.5th and 97.5th percentiles: rank = (25 * R + 999) // 1000 and (975 * R + 999) // 1000, value = sorted[rank - 1].
5. verdict: "B is faster" if low > 0, "B is slower" if high < 0, otherwise "no clear difference".

Output: {"p95_a": [per run, in input order], "p95_b": [...], "diff_ms": diff, "ci_ms": [low, high], "verdict": ...}. Round diff_ms, low and high to 1 decimal with round(); decide the verdict on the unrounded values.
Errors, checked in this order: {"error": "need at least 3 runs per side"} when a or b has fewer than 3 runs; {"error": "empty run"} when any run has no samples.

Example: A''s runs have p95s 210, 215 and 205 ms and B''s 150, 160 and 155 ms: diff_ms is 55.0, every resample difference is positive, and the verdict is "B is faster".', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
