-- challenge chal_quiz_qpr_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_421', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-4-2' AND is_deleted = false LIMIT 1), 'littles-law-sizing', 'Little''s Law: size it, then check what it cannot tell you', 'Two statements on exam-day numbers for POST /api/submissions: sizing the resources behind the endpoint with L = X x W, and what Little''s Law does not predict when you add load to a saturated system.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_421'), 'Capacity review for exam day, POST /api/submissions:
  design load                    408 submissions/s (forecast 340/s + 20%)
  DB connection held per submit  38 ms on average (traces, span db.pool.acquire to release)
  grading per submission         1.6 s in a grader sandbox (async, after the 202 Accepted)
  current sizes                  DB pools 4 instances x 10 connections, grader fleet 400 sandboxes

Statement: "At 408 submissions/s the graders need about 653 busy sandboxes on average, so with 400 sandboxes the grading queue grows for as long as the peak lasts, while the DB pool needs only about 16 busy connections."', 'single_choice'::question_type, 'True. Little''s Law gives the mean number of busy units as throughput x time held: 408/s x 1.6 s = 652.8 sandboxes and 408/s x 0.038 s = 15.5 connections. 400 sandboxes can finish at most 400 / 1.6 s = 250 gradings per second, so during the peak about 158 submissions per second join the grading queue and wait longer and longer. Making grading async keeps the submit request fast, but it does not remove the work: it moves the bottleneck to a queue that no latency graph of the endpoint shows. The misconception is to size only what the request holds while it runs.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_421'), 'k6 closed-model test of POST /api/submissions on staging, steady state (ramp-up excluded):
  vus .......................: 680   (no think time)
  http_reqs .................: 340/s
  http_req_duration .........: avg=2.0s  p(95)=3.1s
  API CPU 40%, DB pool: 100% in use, 210 requests waiting for a connection

Statement: "By Little''s Law, doubling the virtual users to 1,360 will double the throughput to about 680 req/s, because throughput equals concurrency divided by latency."', 'single_choice'::question_type, 'False. L = X x W holds for averages over a stable period, and these numbers fit it (680 = 340/s x 2.0 s), but it is an identity, not a model of the system: it does not say which of the three numbers changes when you add load. Here the pool is saturated (100% in use, a queue of waiters), so throughput is capped near 340/s by the first bottleneck. Twice the VUs means twice as many requests in the system; the law then says W doubles to about 4 s while X stays near 340/s - the extra VUs only wait in the pool queue. The misconception is to read the law as ''more concurrency gives more throughput''.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_qpr_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_qpr_422', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-4-2' AND is_deleted = false LIMIT 1), 'check-a-load-test-report', 'Check a load test report with Little''s Law', 'The summary of capacity-review run cr-200 for POST /api/submissions said 200 virtual users with no think time, a mean latency of 105 ms and 340 requests per second. Those three numbers cannot all describe the same closed loop: 200 VUs that send their next request as soon as the previous answer arrives would send about 1,905 requests per second at 105 ms. The CodeDev team now runs every report through a checker before anyone sizes production from it. Write check_report(case).

Input (stdin, one test case; all numbers are integers, times in ms): {"tolerance_pct": T, "target_utilization_pct": U, "report": {"duration_s", "requests" (both for the steady-state window), "throughput_rps" (the summary line, or null), "mean_latency_ms", "vus" (closed model: virtual users, or null for an open model), "think_time_ms", "mean_in_flight" (measured mean concurrency, or null)}, "resources": [{"name", "size", "hold_ms"}]} - each request holds one unit of a resource for hold_ms on average.

Compute, with X = requests / duration_s (req/s), R = mean_latency_ms, Z = think_time_ms:
- in_flight = X x R / 1000 (Little''s Law, L = X x W with W in seconds)
- closed_limit_rps = vus x 1000 / (R + Z) (a closed loop: N = X x (R + Z)); null when vus is null
- per resource: needed = X x hold_ms / 1000; utilization_pct = needed x 100 / size; min_size = ceil(needed x 100 / U)

"a differs from b" means |a - b| x 100 > T x b: a gap of exactly T% is not a difference.
Findings, in this order:
- "throughput_mismatch": throughput_rps is not null and differs from X
- "above_closed_limit": vus is not null and X x 100 > (100 + T) x closed_limit_rps
- "idle_virtual_users": vus is not null and X x 100 < (100 - T) x closed_limit_rps
- "in_flight_mismatch": mean_in_flight is not null and differs from in_flight
- then for each resource, in input order: "over_capacity:<name>" when needed > size, otherwise "above_target:<name>" when utilization_pct > U
verdict: "impossible" when there is any finding other than idle_virtual_users and above_target:*; otherwise "suspicious" when idle_virtual_users is present; otherwise "consistent".

Output: {"throughput_rps": X, "in_flight", "closed_limit_rps", "resources": [{"name", "needed", "utilization_pct", "min_size"}], "findings": [...], "verdict": ...}, with X, in_flight, closed_limit_rps, needed and utilization_pct rounded to 1 decimal with round(). Do every comparison and the ceiling in exact arithmetic (integers or fractions.Fraction): the tests contain values that sit exactly on a boundary, where floating point can land on the wrong side.

Invalid input: {"error": "invalid <field>"} for the first failing check in this order: duration_s <= 0, requests < 0, mean_latency_ms <= 0, think_time_ms < 0, vus <= 0 (when not null); then, per resource in order, size <= 0 or hold_ms < 0 gives {"error": "invalid resource <name>"}.

Example: run cr-200 (300 s, 102,000 requests, 200 VUs, 105 ms, no think time, a DB pool of 18 held 38 ms, T = 10, U = 70) gives X = 340.0, in_flight = 35.7, closed_limit_rps = 1904.8, the pool needs 12.9 connections (71.8%, min_size 19), and the findings ["idle_virtual_users", "above_target:db_pool"]: verdict "suspicious".', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 1, 'Run cr-200 reports 200 virtual users, no think time and 105 ms per request. If every VU sends its next request the moment the previous answer arrives, how many requests per second should 200 VUs send - and what does it mean that the report counted only 340 per second?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 2, 'Take X from requests / duration_s, never from the summary line, and use that one X everywhere. Keep milliseconds and seconds apart: L = X x W needs W in seconds. Then look at the boundaries: ''more than'' is strict, and the hidden tests put values exactly on the tolerance, on 100% of a resource and on the target, where a float can land one side or the other - Fraction(requests, duration_s) keeps every step exact.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 3, 'The same checks on other numbers: 72,000 requests in 600 s give X = 120 req/s. A mean latency of 250 ms gives in_flight = 120 x 0.25 = 30. 100 VUs with 500 ms think time give closed_limit = 100 x 1000 / 750 = 133.3 req/s; with T = 10, X would be idle only if 120 x 100 < 90 x 133.33..., that is 12,000 < 12,000 - false, a boundary case. A pool held 45 ms per request needs 120 x 0.045 = 5.4 units on average; at U = 60, min_size = ceil(5.4 x 100 / 60) = 9.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
