VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 'Run cr-200: 200 VUs, no think time, 105 ms, yet only 340 req/s', '{"tolerance_pct":10,"target_utilization_pct":70,"report":{"duration_s":300,"requests":102000,"throughput_rps":340,"mean_latency_ms":105,"vus":200,"think_time_ms":0,"mean_in_flight":36},"resources":[{"name":"api_workers","size":60,"hold_ms":105},{"name":"db_pool","size":18,"hold_ms":38}]}', '{"throughput_rps":340,"in_flight":35.7,"closed_limit_rps":1904.8,"resources":[{"name":"api_workers","needed":35.7,"utilization_pct":59.5,"min_size":51},{"name":"db_pool","needed":12.9,"utilization_pct":71.8,"min_size":19}],"findings":["idle_virtual_users","above_target:db_pool"],"verdict":"suspicious"}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 'Consistent: 600 VUs with 1,645 ms think time give 340 req/s', '{"tolerance_pct":10,"target_utilization_pct":70,"report":{"duration_s":300,"requests":102000,"throughput_rps":340,"mean_latency_ms":120,"vus":600,"think_time_ms":1645,"mean_in_flight":42},"resources":[{"name":"api_workers","size":60,"hold_ms":120},{"name":"db_pool","size":24,"hold_ms":38}]}', '{"throughput_rps":340,"in_flight":40.8,"closed_limit_rps":339.9,"resources":[{"name":"api_workers","needed":40.8,"utilization_pct":68,"min_size":59},{"name":"db_pool","needed":12.9,"utilization_pct":53.8,"min_size":19}],"findings":[],"verdict":"consistent"}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 'Summary says 410 req/s, but requests / duration give 340', '{"tolerance_pct":10,"target_utilization_pct":70,"report":{"duration_s":300,"requests":102000,"throughput_rps":410,"mean_latency_ms":120,"vus":null,"think_time_ms":0,"mean_in_flight":41},"resources":[{"name":"api_workers","size":60,"hold_ms":120},{"name":"db_pool","size":20,"hold_ms":38}]}', '{"throughput_rps":340,"in_flight":40.8,"closed_limit_rps":null,"resources":[{"name":"api_workers","needed":40.8,"utilization_pct":68,"min_size":59},{"name":"db_pool","needed":12.9,"utilization_pct":64.6,"min_size":19}],"findings":["throughput_mismatch"],"verdict":"impossible"}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), '50 VUs at 200 ms cannot send 340 req/s; in-flight gauge disagrees too', '{"tolerance_pct":10,"target_utilization_pct":70,"report":{"duration_s":600,"requests":204000,"throughput_rps":340,"mean_latency_ms":200,"vus":50,"think_time_ms":0,"mean_in_flight":50},"resources":[{"name":"api_workers","size":128,"hold_ms":200},{"name":"db_pool","size":10,"hold_ms":38},{"name":"grader_workers","size":60,"hold_ms":1600}]}', '{"throughput_rps":340,"in_flight":68,"closed_limit_rps":250,"resources":[{"name":"api_workers","needed":68,"utilization_pct":53.1,"min_size":98},{"name":"db_pool","needed":12.9,"utilization_pct":129.2,"min_size":19},{"name":"grader_workers","needed":544,"utilization_pct":906.7,"min_size":778}],"findings":["above_closed_limit","in_flight_mismatch","over_capacity:db_pool","over_capacity:grader_workers"],"verdict":"impossible"}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 'Boundaries: exactly 10% apart, needed equal to size, exactly 70% busy, ceil(21 x 100 / 70)', '{"tolerance_pct":10,"target_utilization_pct":70,"report":{"duration_s":300,"requests":63000,"throughput_rps":231,"mean_latency_ms":100,"vus":210,"think_time_ms":800,"mean_in_flight":23},"resources":[{"name":"db_pool","size":21,"hold_ms":100},{"name":"redis_pool","size":30,"hold_ms":100},{"name":"api_workers","size":32,"hold_ms":100}]}', '{"throughput_rps":210,"in_flight":21,"closed_limit_rps":233.3,"resources":[{"name":"db_pool","needed":21,"utilization_pct":100,"min_size":30},{"name":"redis_pool","needed":21,"utilization_pct":70,"min_size":30},{"name":"api_workers","needed":21,"utilization_pct":65.6,"min_size":30}],"findings":["above_target:db_pool"],"verdict":"consistent"}', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_qpr_422'), 'Negative think time is an invalid report', '{"tolerance_pct":10,"target_utilization_pct":70,"report":{"duration_s":300,"requests":102000,"throughput_rps":340,"mean_latency_ms":120,"vus":200,"think_time_ms":-500,"mean_in_flight":null},"resources":[{"name":"db_pool","size":18,"hold_ms":38}]}', '{"error":"invalid think_time_ms"}', 2, false, true, 6),
