-- challenge chal_quiz_qpr_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_431', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-4-3' AND is_deleted = false LIMIT 1), 'valid-benchmark-or-not', 'Valid benchmark or not? Environment, data, think time and the load model', 'Three statements on benchmarks of the CodeDev API: a staging run with a tiny data set, a k6 script without think time, and a closed-model test during a slowdown. For each, decide whether the benchmark measures what its report claims.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431'), 'Benchmark report BM-0907, GET /api/leaderboard?courseId=<id>:
  environment   staging; same build, same instance type (4 vCPU, 16 GB) and same PostgreSQL 18
                configuration as production
  data          seed script: 500 users, 3 courses, 4,200 submissions
  result        300 req/s for 10 min, p95 18 ms, 0 errors

Production today: 1.2M users, 340 courses, 61M submissions.

Statement: "Because staging runs the same build on the same instance type with the same database configuration, the 18 ms p95 is a good estimate of the leaderboard''s p95 in production at 300 req/s."', 'single_choice'::question_type, 'False. The data is part of the environment. 4,200 submissions fit in a few hundred kilobytes, so every query runs from memory and any plan is fast, including a sequential scan and an in-memory sort. With 61 million rows the planner may choose different plans, sorts can spill to disk, and the working set no longer fits in the cache, so the buffer hit ratio drops. The same build and hardware with a data set 15,000 times smaller measures a different system. The misconception is that matching the code and the machine is enough; benchmark on production-like volume and distribution (how many submissions the biggest course has, not only the average).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431'), 'k6 script used for the report "Leaderboard holds 1,000 concurrent learners":
  export const options = { vus: 1000, duration: "10m" };
  export default function () {
    http.get(`${BASE}/api/leaderboard?courseId=42`);
  }
Result: mean http_req_duration 200 ms.
Product analytics: a learner on the leaderboard page reloads it about every 30 s.

Statement: "Without a sleep() between iterations, these 1,000 VUs send roughly 5,000 requests per second, about 150 times what 1,000 real learners send, so the test measures a much heavier load than its title says."', 'single_choice'::question_type, 'True. A closed-loop VU sends its next request as soon as the previous one returns, so N = X x (R + Z) gives X = 1,000 / 0.2 s = 5,000 req/s with no think time. 1,000 real learners with about 30 s between reloads send 1,000 / (30 + 0.2) s, about 33 req/s. 5,000 / 33 is about 150. The report''s title counts VUs, but the server feels requests per second. Either add realistic think time (sleep with a spread around 30 s) or, better, state the load as a request rate. The misconception is to treat a VU as a user.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431'), 'Closed-model k6 test of POST /api/submissions, 50 VUs, no think time. Halfway through, a migration took a lock and latency rose for two minutes:
  before the lock   http_req_duration avg=100ms   http_reqs 500/s   errors 0%
  during the lock   http_req_duration avg=1s      http_reqs 50/s    errors 0%
  after the lock    http_req_duration avg=100ms   http_reqs 500/s   errors 0%

Statement: "The test shows that during a slowdown like this the API receives ten times fewer submissions, so on exam day the backlog stays small and the system recovers by itself."', 'single_choice'::question_type, 'False. In a closed model each VU waits for its answer before sending the next request, so when the server slowed down the load generator slowed down with it: 50 VUs / 1 s = 50 req/s. That is a property of the test, not of the learners. On exam day submissions arrive independently of the server''s latency (an open model): about 340 per second keep coming during the lock, and every second the API cannot keep up adds to a queue. To see that, use an open-model executor (k6 constant-arrival-rate, wrk2 -R) and watch dropped iterations and the queue. The misconception is to read a closed-loop throughput drop as ''less demand''.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_431') AND order_index = 3)
    RETURNING id
)
