-- challenge chal_quiz_qpr_511 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_511', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 5 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-5-1' AND is_deleted = false LIMIT 1), 'slos-from-load-tests', 'What can this load test promise?', 'Two statements on turning exam-day load test results into an objective for POST /api/submissions: what a p95 under the threshold proves, and what a short failure at the forecast peak costs the 28-day error budget.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_511');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_511');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_511'), 'Steady-state part of a rerun at 340 req/s, constant-arrival-rate, 30 min (k6-style output, abbreviated):

submit_duration (POST /api/submissions, scenario=peak)
  avg=581ms  med=388ms  p(90)=1.12s  p(95)=1.38s  max=10s
http_req_failed (scenario=peak; 400/413/422 marked expected)
  0.21%  (1,285 of 612,000) - all 503 from the admission limiter

Proposed objective: 99.9% of valid submissions accepted (202) within 2 s.

Statement: "This run shows the submit endpoint can meet the proposed objective at 340 req/s."', 'single_choice'::question_type, 'False. p95 = 1.38 s only proves that at least 95% of the samples took at most 2 s (nearest-rank: p95 <= 2 s is the same as "at least 95% within 2 s"). The objective needs 99.9%, so at most 0.1% of valid requests may be bad. The 1,285 limiter 503s are valid requests that the platform refused, 0.21% of the run, which alone is about twice the allowed 0.1% before any slow 202 is counted. The 503s are fast, so they even pull the latency percentiles down. The misconception is that a percentile under the threshold means the success objective is met; write the objective as good / valid and compute it from the samples.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_511') AND order_index = 1)
    RETURNING id
)
