-- challenge chal_quiz_qpr_521 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_521', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 5 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-5-2' AND is_deleted = false LIMIT 1), 'chaos-experiment-hypothesis', 'Read a chaos experiment record', 'Two statements on chaos experiments against the submit path: what a resource metric as the steady state can prove, and when an abort condition on consecutive minutes stops the injection.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_521');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_521');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_521'), 'Experiment record H-12 (staging, load test at 200 submissions/s):

fault:        stop grader node g2 (one of 4) at 15:10 for 10 min
steady state: average CPU of the remaining grader nodes < 85%
result:       CPU 15:10-15:20 between 71% and 78%  ->  hypothesis confirmed

Same run, from the load generator (not in the record):
minute    submit good ratio   time to result p95
15:09         99.8%               6.1 s
15:12         99.7%              48.0 s
15:16         99.6%              97.0 s
15:20         99.6%             141.0 s

Statement: "This record shows that learners were not affected by losing one grader node."', 'single_choice'::question_type, 'False. CPU is a resource metric: it says the surviving nodes were busy but below 85%, and that fits a grading queue that keeps growing, because grading is limited by the number of sandbox slots per node, not by CPU. Acceptance stayed fine (the submit good ratio is about the 202 within 2 s), but the time from acceptance to result grew from 6 s to 141 s and was still rising: learners waited minutes for their results. The steady state of an experiment must be an output metric learners feel, here both acceptance and time to result; resource metrics belong in the diagnostics and the hard guards. The misconception is that "within its bound" on any metric confirms the hypothesis; it only confirms what that metric can see.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_521') AND order_index = 1)
    RETURNING id
)
