WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_521'), 'Abort condition of experiment H-17: stop the injection when the submit good ratio is below 99.0% for 2 consecutive minutes. The runner checks it at the end of every minute. No other abort condition fired.

minute   submit good ratio
10:01        99.7%
10:02        98.6%
10:03        99.2%
10:04        98.4%
10:05        97.9%

Statement: "The runner stops the injection at the end of minute 10:05, not earlier."', 'single_choice'::question_type, 'True. 10:02 is below 99.0%, but 10:03 is above it, so the run of consecutive bad minutes resets to zero. 10:04 is the first bad minute of a new run and 10:05 the second, so the condition is met at the end of 10:05. Stopping at 10:04 would count two bad minutes that are not consecutive. Requiring consecutive minutes is deliberate: one bad minute can be noise, two in a row are a trend. The common mistake is to count bad minutes in total, which aborts on noise and makes the abort rule mean something different from what was agreed.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_521') AND order_index = 2)
    RETURNING id
)
