-- challenge chal_quiz_qpr_531 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_qpr_531', (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'qa-performance-reliability') AND order_index = 5 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-qpr-5-3' AND is_deleted = false LIMIT 1), 'capacity-plan-evidence', 'Check the numbers in an exam-day capacity plan', 'Three statements on draft capacity plans for 340 submissions/s at the exam-day peak: capacity from CPU utilisation, grader sandboxes from Little''s Law, and API instances after one fails.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531'), 'Draft plan, section "API capacity":

load test (steady state): 340 req/s POST /api/submissions on 4 API instances
API CPU: 40% average, 46% on the busiest instance
submit p95: 6.2 s, pool wait p95: 5.8 s (pool size 10 per instance)

conclusion: capacity = 340 / 0.40 = 850 req/s

Statement: "The CPU reading supports 850 req/s as the capacity of these 4 instances."', 'single_choice'::question_type, 'False. Dividing the load by CPU utilisation assumes CPU is the first resource to run out and that latency stays acceptable until CPU reaches 100%. The same evidence shows the opposite: at 340 req/s requests already wait 5.8 s (p95) for a pool connection and the submit p95 is 6.2 s, so the objective is broken at 340 req/s with CPU at 40%. The first bottleneck is the pool, not CPU. Capacity is the highest load at which the objective still holds, found with a step test (the knee), not an extrapolation of one resource. The misconception is that idle CPU means spare capacity.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531') AND order_index = 1)
    RETURNING id
)
