WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531'), 'Evidence for the grader:

design load: 408 submissions/s (forecast 340/s + 20% forecast error)
mean grading time per submission (steady state at 340/s): 1.6 s
one grader node runs 24 sandboxes; queue wait grows sharply above ~80% busy

Draft plan: 30 grader nodes.

Statement: "With 30 nodes, the average sandbox utilisation at the design load would be above 90%."', 'single_choice'::question_type, 'True. Little''s Law (L = lambda x W) gives the average number of busy sandboxes: 408/s x 1.6 s = 652.8. Thirty nodes have 30 x 24 = 720 sandboxes, so the average utilisation is 652.8 / 720 = 90.7%, above the ~80% where queue wait grows sharply, and with no room for one node to fail. Keeping utilisation at most 80% needs 652.8 / 0.8 = 816 sandboxes, 34 nodes. The misconception is to size workers by the arrival rate alone (408 jobs per second sounds like it needs few machines) and forget that each job holds a sandbox for 1.6 s.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531') AND order_index = 2)
    RETURNING id
)
