SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531'), 'Step test per API instance (steady state per step, objective: 99.5% of valid submits accepted within 2 s):

per instance   100/s   110/s   120/s   130/s   140/s   150/s
submit SLI     99.9%   99.9%   99.8%   99.7%   99.1%   96.4%

Load balancer in the same test: the busiest instance received up to 10% more than the mean.
Draft plan: 5 API instances for a design load of 408 submissions/s.

Statement: "If one of the 5 instances fails at the design load, even the busiest remaining instance stays at or below 130/s, the highest step where the objective held."', 'single_choice'::question_type, 'True. With 4 instances left, the mean load is 408 / 4 = 102/s per instance, and the busiest one receives up to 10% more: 102 x 1.1 = 112.2/s, under 130/s. So the draft survives one failure within measured capacity, though with less margin than a plan at 100/s per instance after a loss would give. The common mistake is to forget either the failed unit (checking 408 / 5 instead of 408 / 4) or the balancing skew (checking the mean instead of the busiest instance); a defensible plan checks the busiest unit in the failure case against the measured step, not against a guess.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_qpr_531') AND order_index = 3)
    RETURNING id
)
